package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the new today from the body; refuses anything that is not a calendar date. */
public class ValidateToday {

    public record TodayRequest(String today) {
    }

    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today) throws InvalidTodayException {
        String raw = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(raw));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException(raw);
        }
    }
}
package net.officefloor.hq.app.sheet;

/** A today that is not a calendar date (YYYY-MM-DD). */
public class InvalidTodayException extends Exception {
    public InvalidTodayException(String value) {
        super("Not a date: " + value);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidToday {
    public void handle(@Parameter InvalidTodayException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
handle:
  class: net.officefloor.hq.app.sheet.HandleInvalidToday
-- A sheet's void reasons: trimmed texts, each on the sheet at most once. While the sheet has any, a claim is voided
-- only with one of them.
CREATE TABLE void_reason (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    reason VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);
-- The reason a VOID claim was voided with; null when it was voided without one.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
package net.officefloor.hq.app.voidreason;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface VoidReasonRepository extends JpaRepository<VoidReason, Long> {

    /** The sheet's void reasons, in the order they were added. */
    List<VoidReason> findBySheetIdOrderByIdAsc(String sheetId);

    boolean existsBySheetIdAndReason(String sheetId, String reason);

    boolean existsBySheetId(String sheetId);
}

